Procedure.Body:

SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @now DATETIME = SYSUTCDATETIME();

UPDATE dbo.Accounts
SET LastLoginAt = @now
WHERE [userId] = @userId;

IF @@ROWCOUNT = 0
BEGIN
    INSERT INTO [dbo].[Accounts] ([userId], [createdAt], [lastLoginAt])
    VALUES (@userId, @now, @now);
END


SET NOCOUNT ON;
SET XACT_ABORT ON;

INSERT INTO [dbo].[Characters] ([userId], [username], [gender], [region], [lastRoom])
VALUES (@userId, @username, @gender, @region, @lastRoom);


SET NOCOUNT ON;
SELECT @Exists =
 CASE WHEN EXISTS (
     SELECT 1
     FROM [dbo].[Characters] WITH (READCOMMITTED)
     WHERE username = @username
 )
 THEN 1 ELSE 0 END;


SET NOCOUNT ON;

SELECT
    characterId, username, posX, posY, gender, region, dir, level, money
FROM [dbo].[Characters]
WHERE [userId] = @userId AND [isActive] = 1
ORDER BY [level] DESC;


SET NOCOUNT ON;
SET XACT_ABORT ON;
SELECT
  posX, posY, dir, lastRoom, hp, maxHp, level, exp, money
FROM [dbo].[Characters]
WHERE [characterId] = @characterId


SET NOCOUNT ON;
SET XACT_ABORT ON;

UPDATE [dbo].[Characters]
SET isActive = 0
WHERE [characterId] = @characterId AND [userId] = @userId AND [isActive] = 1;

SELECT @@ROWCOUNT AS affectedRows;


SET NOCOUNT ON;
SET XACT_ABORT ON;

SELECT 
  id, monsterId, itemId, dropRate, minCount, maxCount, isEnabled
FROM [dbo].[MonsterDropItem]
WHERE isEnabled = 1
ORDER BY MonsterId, DropRate DESC;


SET NOCOUNT ON;
SET XACT_ABORT ON;

INSERT INTO [dbo].[EquipmentInstance] ([itemId], [enhancementLevel])
VALUES (@itemId, @enhancementLevel);

SET @newEquipmentInstanceId = SCOPE_IDENTITY();


SET NOCOUNT ON;
SET XACT_ABORT ON;

UPDATE [dbo].[EquipmentInstance]
SET enhancementLevel = @enhancementLevel
WHERE equipmentInstanceId = @equipmentInstanceId;


SET NOCOUNT ON;
SET XACT_ABORT ON;

DELETE FROM [dbo].[EquipmentInstance]
WHERE equipmentInstanceId = @equipmentInstanceId;


SET NOCOUNT ON;
SET XACT_ABORT ON;

DELETE FROM [dbo].[CharacterEquipment]
WHERE characterId = @characterId AND slotType = @slotType;


SET NOCOUNT ON;
SET XACT_ABORT ON;

DELETE FROM [dbo].[CharacterInventory]
WHERE characterId = @characterId AND slotIndex = @slotIndex;
